//! polyplug guest library — Rust bindings for guest-side (plugin developer) use.
//!
//! This crate provides the ABI types, allocator hookup, and registration
//! helpers that plugin authors need to implement a polyplug contract.
//!
//! # Status
//! Scaffold only. Full implementation is code-generated by `polyplugc`.

// Re-export the runtime ABI types that plugins need.
pub use polyplug::abi::ABI_ERROR_GENERIC;
pub use polyplug::abi::ABI_ERROR_PANIC;
pub use polyplug::abi::ABI_OK;
pub use polyplug::abi::AbiError;
pub use polyplug::abi::PluginDescriptor;
pub use polyplug::abi::PluginHandle;
pub use polyplug::abi::PluginRegistrar;
pub use polyplug::abi::PluginVTable;
pub use polyplug::abi::StringView;
pub use polyplug::allocator::polyplug_host_alloc;
pub use polyplug::allocator::polyplug_host_free;

/// Error returned from guest-side plugin trait methods.
///
/// Produced by generated ABI wrappers when an ABI call returns a non-zero code.
/// Plugin developers return `Result<T, PluginError>` from their trait implementations.
#[derive(Debug)]
pub struct PluginError {
    /// ABI error code (non-zero).
    pub code: u32,
    /// Human-readable error message. May be empty.
    pub message: String,
}

impl core::fmt::Display for PluginError {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        write!(
            f,
            "PluginError(code={}, message={})",
            self.code, self.message
        )
    }
}
